const systemPrompt = msgAtual.eh_thiago ? promptDono : promptRecepcionista;

// Montar parts do Gemini - audio inline se tiver
const parts = [];
if (temAudio) {
  parts.push({ inline_data: { mime_type: msgAtual.audio_mime || 'audio/ogg', data: msgAtual.audio_base64 } });
  parts.push({ text: 'Esta e a mensagem em audio do contato. Transcreva e decida a acao conforme o system prompt.' });
} else {
  parts.push({ text: msgAtual.texto || '(sem texto)' });
}

return [{
  json: {
    eh_thiago: msgAtual.eh_thiago,
    sender_numero: msgAtual.sender_numero,
    sender_nome_push: msgAtual.sender_nome_push,
    texto_original: msgAtual.texto || '',
    tem_audio: !!temAudio,
    timestamp_brasilia: msgAtual.timestamp_agora_brasilia,
    lead_id_atual: lead ? lead.id : null,
    gemini_body: {
      contents: [{ parts: parts }],
      systemInstruction: { parts: [{ text: systemPrompt }] },
      generationConfig: { temperature: 0.3, maxOutputTokens: 2000, responseMimeType: 'application/json' }
    }
  }
}];

// Parseia resposta Gemini e monta SQL/HTTP da acao escolhida
const prev = $('Montar Prompt').first().json;
const geminiResp = items[0].json;

let rawText = '';
try { rawText = geminiResp.candidates?.[0]?.content?.parts?.[0]?.text || ''; } catch(e) {}

function parseJson(s) {
  if (!s) return null;
  let t = String(s).trim().replace(/^```json\s*/i, '').replace(/```$/g, '').trim();
  const i = t.indexOf('{'); const j = t.lastIndexOf('}');
  if (i >= 0 && j > i) t = t.substring(i, j+1);
  try { return JSON.parse(t); } catch(e) { return null; }
}

const dec = parseJson(rawText) || { acao: 'apenas_responder', parametros: {}, resposta: 'Desculpa, tive um problema processando. Pode repetir?' };
let acao = dec.acao || 'apenas_responder';
const p = dec.parametros || {};

// Fallback defensivo: se Gemini escolheu agendar_mensagem/enviar_agora pra
// um numero do Thiago, isso na verdade eh um lembrete (ele falou consigo mesmo).
const THIAGO_NUMEROS_FB = ['5511964486564', '5511910441709'];
const destNum = String(p.destinatario_numero || '').replace(/[^0-9]/g,'');
if (['agendar_mensagem','enviar_agora'].includes(acao) && THIAGO_NUMEROS_FB.includes(destNum)) {
  if (acao === 'agendar_mensagem') {
    acao = 'criar_lembrete';
    p.descricao = p.descricao || p.texto || p.conteudo || prev.texto_original || 'lembrete';
  } else {
    acao = 'apenas_responder';
    dec.resposta = 'Pra voce mesmo seria um lembrete imediato? Manda assim: "me lembra daqui X minutos de Y".';
  }
}
const esc = s => String(s == null ? '' : s).replace(/'/g, "''");
const escOrNull = s => (s == null || s === '') ? 'NULL' : `'${esc(s)}'`;

// Texto original: se foi audio usa transcricao, senao usa o texto que veio
const textoSalvarMemoria = prev.tem_audio
  ? (dec.transcricao_audio || '[audio sem transcricao]')
  : (prev.texto_original || '');

let acao_tipo = 'REPLY_ONLY';
let sql_query = '';
let send_to_number = '';
let send_text = '';

const senderNumero = prev.sender_numero;
const senderNomePush = prev.sender_nome_push || '';

if (prev.eh_thiago) {
  // Validacao defensiva: se Gemini escolheu enviar mas o numero veio vazio/invalido,
  // degrada pra apenas_responder ao inves de quebrar com 'Missing required fields'.
  if (['agendar_mensagem','enviar_agora'].includes(acao)) {
    const numLimpo = String(p.destinatario_numero || '').replace(/[^0-9]/g, '');
    if (numLimpo.length < 10) {
      acao = 'apenas_responder';
      dec.resposta = 'Nao identifiquei o numero do destinatario. Me passa o numero (55DDNNNNNNNNN) ou o nome exato dos contatos conhecidos.';
    }
  }
  if (acao === 'salvar_ideia') {
    acao_tipo = 'DB_OP';
    const tagsArr = Array.isArray(p.tags) ? p.tags.filter(Boolean) : [];
    const tagsSql = tagsArr.length ? `ARRAY[${tagsArr.map(t=>`'${esc(t)}'`).join(',')}]::TEXT[]` : 'NULL';
    sql_query = `INSERT INTO giulia_ideias (conteudo, tags) VALUES ('${esc(p.conteudo)}', ${tagsSql}) RETURNING id, conteudo;`;
  } else if (acao === 'salvar_contato') {
    const numContato = String(p.destinatario_numero || p.numero || '').replace(/[^0-9]/g, '');
    if (!numContato || numContato.length < 10) {
      acao = 'apenas_responder';
      dec.resposta = 'Pra salvar o contato preciso do numero (55DDNNNNNNNNN). Me manda o numero junto com o nome.';
    } else {
      acao_tipo = 'DB_OP';
      const apelidosArr = Array.isArray(p.tags) ? p.tags.filter(Boolean) : (Array.isArray(p.apelidos) ? p.apelidos.filter(Boolean) : []);
      const apelidosSql = apelidosArr.length ? `ARRAY[${apelidosArr.map(t=>`'${esc(t)}'`).join(',')}]::TEXT[]` : 'NULL';
      const nome = p.destinatario_nome || p.nome || ('Contato ' + numContato);
      sql_query = `INSERT INTO giulia_contatos (nome, apelidos, numero, observacoes) VALUES ('${esc(nome)}', ${apelidosSql}, '${esc(numContato)}', ${escOrNull(p.observacoes)}) ON CONFLICT (numero) DO UPDATE SET nome = COALESCE(EXCLUDED.nome, giulia_contatos.nome), apelidos = COALESCE(EXCLUDED.apelidos, giulia_contatos.apelidos), observacoes = COALESCE(EXCLUDED.observacoes, giulia_contatos.observacoes) RETURNING id, nome, numero;`;
    }
  } else if (acao === 'criar_lembrete') {
    acao_tipo = 'DB_OP';
    const rec = p.recorrencia ? `'${esc(p.recorrencia)}'` : 'NULL';
    const desc = p.descricao || prev.texto_original || 'lembrete';
    sql_query = `INSERT INTO giulia_lembretes (descricao, disparar_em, recorrencia) VALUES ('${esc(desc)}', '${esc(p.disparar_em)}'::TIMESTAMP, ${rec}) RETURNING id, descricao, disparar_em;`;
  } else if (acao === 'agendar_mensagem') {
    acao_tipo = 'DB_OP';
    sql_query = `INSERT INTO giulia_mensagens_agendadas (destinatario_numero, destinatario_nome, conteudo, agendado_para) VALUES ('${esc(p.destinatario_numero)}', '${esc(p.destinatario_nome)}', '${esc(p.texto)}', '${esc(p.disparar_em || p.agendado_para)}'::TIMESTAMP) RETURNING id, destinatario_nome, agendado_para;`;
  } else if (acao === 'enviar_agora') {
    acao_tipo = 'SEND_NOW';
    send_to_number = String(p.destinatario_numero || '').replace(/[^0-9]/g,'');
    send_text = String(p.texto || '');
  } else if (acao === 'listar_ideias') {
    acao_tipo = 'DB_OP';
    const tag = p.filtro_tag ? esc(p.filtro_tag) : null;
    sql_query = tag
      ? `SELECT id, conteudo, tags, created_at FROM giulia_ideias WHERE '${tag}' = ANY(tags) ORDER BY created_at DESC LIMIT 20;`
      : `SELECT id, conteudo, tags, created_at FROM giulia_ideias ORDER BY created_at DESC LIMIT 20;`;
  } else if (acao === 'listar_lembretes') {
    acao_tipo = 'DB_OP';
    sql_query = `SELECT id, descricao, disparar_em, recorrencia, status FROM giulia_lembretes WHERE status = 'pendente' ORDER BY disparar_em ASC LIMIT 20;`;
  } else if (acao === 'listar_leads') {
    acao_tipo = 'DB_OP';
    sql_query = `SELECT id, nome, numero, tipo_projeto, porte, localizacao, fase, resumo, status, criado_em FROM giulia_leads WHERE status IN ('novo','em_atendimento','agendado') ORDER BY criado_em DESC LIMIT 20;`;
  } else if (acao === 'listar_reunioes') {
    acao_tipo = 'DB_OP';
    sql_query = `SELECT id, nome_cliente, numero_cliente, agendado_para, assunto, status FROM giulia_reunioes WHERE status IN ('pendente_aprovacao_thiago','agendada','confirmada') ORDER BY agendado_para ASC LIMIT 20;`;
  } else if (acao === 'listar_notificacoes') {
    acao_tipo = 'DB_OP';
    sql_query = `SELECT id, tipo, origem_nome, origem_numero, resumo, urgencia, criada_em FROM giulia_notificacoes_thiago WHERE status = 'pendente' ORDER BY criada_em DESC LIMIT 20;`;
  } else if (acao === 'aprovar_reuniao' && p.id_reuniao) {
    acao_tipo = 'DB_OP';
    sql_query = `UPDATE giulia_reunioes SET status = 'agendada', confirmada_em = NOW() WHERE id = ${parseInt(p.id_reuniao,10)} RETURNING id, nome_cliente, numero_cliente, agendado_para;`;
  } else if (acao === 'registrar_gasto') {
    acao_tipo = 'DB_OP';
    const tagsArr = Array.isArray(p.tags) ? p.tags.filter(Boolean) : [];
    const tagsSql = tagsArr.length ? `ARRAY[${tagsArr.map(t=>`'${esc(t)}'`).join(',')}]::TEXT[]` : 'NULL';
    const valor = parseFloat(p.valor) || 0;
    const dataGasto = p.data_gasto && p.data_gasto.length >= 10 ? `'${esc(p.data_gasto.substring(0,10))}'::DATE` : 'CURRENT_DATE';
    sql_query = `INSERT INTO giulia_gastos (descricao, valor, categoria, forma_pagamento, tags, data_gasto, observacoes) VALUES ('${esc(p.descricao || p.conteudo)}', ${valor}, ${escOrNull(p.categoria)}, ${escOrNull(p.forma_pagamento)}, ${tagsSql}, ${dataGasto}, ${escOrNull(p.observacoes)}) RETURNING id, descricao, valor, categoria;`;
  } else if (acao === 'listar_gastos') {
    acao_tipo = 'DB_OP';
    const where = [];
    if (p.filtro_categoria) where.push(`categoria = '${esc(p.filtro_categoria)}'`);
    if (p.valor_min) where.push(`valor >= ${parseFloat(p.valor_min)}`);
    if (p.valor_max) where.push(`valor <= ${parseFloat(p.valor_max)}`);
    const periodoMap = { hoje: "data_gasto = CURRENT_DATE", semana: "data_gasto >= CURRENT_DATE - INTERVAL '7 days'", mes: "data_gasto >= date_trunc('month', CURRENT_DATE)", '30dias': "data_gasto >= CURRENT_DATE - INTERVAL '30 days'", ano: "data_gasto >= date_trunc('year', CURRENT_DATE)" };
    if (p.filtro_periodo && periodoMap[p.filtro_periodo]) where.push(periodoMap[p.filtro_periodo]);
    const whereSql = where.length ? 'WHERE ' + where.join(' AND ') : '';
    sql_query = `SELECT id, descricao, valor, categoria, forma_pagamento, data_gasto FROM giulia_gastos ${whereSql} ORDER BY data_gasto DESC, id DESC LIMIT 30;`;
  } else if (acao === 'resumo_gastos') {
    acao_tipo = 'DB_OP';
    const periodoMap = { hoje: "WHERE data_gasto = CURRENT_DATE", semana: "WHERE data_gasto >= CURRENT_DATE - INTERVAL '7 days'", mes: "WHERE data_gasto >= date_trunc('month', CURRENT_DATE)", '30dias': "WHERE data_gasto >= CURRENT_DATE - INTERVAL '30 days'", ano: "WHERE data_gasto >= date_trunc('year', CURRENT_DATE)" };
    const whereSql = (p.filtro_periodo && periodoMap[p.filtro_periodo]) ? periodoMap[p.filtro_periodo] : "WHERE data_gasto >= date_trunc('month', CURRENT_DATE)";
    sql_query = `SELECT COALESCE(categoria,'sem_categoria') AS categoria, COUNT(*) AS qtd, SUM(valor) AS total FROM giulia_gastos ${whereSql} GROUP BY categoria ORDER BY total DESC;`;
  } else if (acao === 'editar_gasto' && p.id_gasto) {
    acao_tipo = 'DB_OP';
    const sets = [];
    if (p.descricao) sets.push(`descricao = '${esc(p.descricao)}'`);
    if (p.valor) sets.push(`valor = ${parseFloat(p.valor)}`);
    if (p.categoria) sets.push(`categoria = '${esc(p.categoria)}'`);
    if (p.forma_pagamento) sets.push(`forma_pagamento = '${esc(p.forma_pagamento)}'`);
    if (p.data_gasto) sets.push(`data_gasto = '${esc(p.data_gasto.substring(0,10))}'::DATE`);
    if (p.observacoes) sets.push(`observacoes = '${esc(p.observacoes)}'`);
    sets.push('sheets_synced = false');
    if (sets.length > 1) {
      sql_query = `UPDATE giulia_gastos SET ${sets.join(', ')} WHERE id = ${parseInt(p.id_gasto,10)} RETURNING id, descricao, valor, categoria;`;
    }
  } else if (acao === 'deletar_gasto' && p.id_gasto) {
    acao_tipo = 'DB_OP';
    sql_query = `DELETE FROM giulia_gastos WHERE id = ${parseInt(p.id_gasto,10)} RETURNING id, descricao, valor;`;
  }
} else {
  if (acao === 'qualificar_lead') {
    acao_tipo = 'DB_OP';
    sql_query = `INSERT INTO giulia_leads (numero, nome, tipo_projeto, porte, localizacao, fase, resumo, status)
 VALUES ('${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, ${escOrNull(p.tipo_projeto)}, ${escOrNull(p.porte)}, ${escOrNull(p.localizacao)}, ${escOrNull(p.fase)}, ${escOrNull(p.resumo)}, 'em_atendimento')
 ON CONFLICT (numero) DO UPDATE SET
   nome = COALESCE(EXCLUDED.nome, giulia_leads.nome),
   tipo_projeto = COALESCE(EXCLUDED.tipo_projeto, giulia_leads.tipo_projeto),
   porte = COALESCE(EXCLUDED.porte, giulia_leads.porte),
   localizacao = COALESCE(EXCLUDED.localizacao, giulia_leads.localizacao),
   fase = COALESCE(EXCLUDED.fase, giulia_leads.fase),
   resumo = COALESCE(EXCLUDED.resumo, giulia_leads.resumo),
   status = CASE WHEN giulia_leads.status = 'novo' THEN 'em_atendimento' ELSE giulia_leads.status END,
   atualizado_em = NOW()
 RETURNING id, nome, tipo_projeto;
 INSERT INTO giulia_notificacoes_thiago (tipo, origem_numero, origem_nome, resumo, urgencia)
 SELECT 'lead_novo', '${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, 'Lead qualificado: ' || COALESCE(${escOrNull(p.tipo_projeto)}, '?') || ' / ' || COALESCE(${escOrNull(p.porte)}, '?') || ' / ' || COALESCE(${escOrNull(p.localizacao)}, '?') || E'\n' || COALESCE(${escOrNull(p.resumo)}, ''), 'normal'
 WHERE NOT EXISTS (SELECT 1 FROM giulia_notificacoes_thiago WHERE origem_numero = '${esc(senderNumero)}' AND tipo = 'lead_novo' AND status = 'pendente');`;
  } else if (acao === 'agendar_reuniao') {
    acao_tipo = 'DB_OP';
    sql_query = `INSERT INTO giulia_leads (numero, nome, status) VALUES ('${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, 'agendado') ON CONFLICT (numero) DO UPDATE SET status = 'agendado', atualizado_em = NOW();
 INSERT INTO giulia_reunioes (lead_id, numero_cliente, nome_cliente, agendado_para, assunto, status)
 VALUES ((SELECT id FROM giulia_leads WHERE numero = '${esc(senderNumero)}'), '${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, '${esc(p.agendado_para)}'::TIMESTAMP, ${escOrNull(p.assunto_reuniao)}, 'pendente_aprovacao_thiago') RETURNING id, agendado_para;
 INSERT INTO giulia_notificacoes_thiago (tipo, origem_numero, origem_nome, resumo, urgencia)
 VALUES ('agendamento_pendente', '${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, 'Cliente pediu reuniao em ${esc(p.agendado_para)}. Assunto: ' || COALESCE(${escOrNull(p.assunto_reuniao)}, '(?)') || E'\nPra aprovar, manda: aprovar reuniao <id>', ${escOrNull(p.urgencia || 'normal')});`;
  } else if (acao === 'notificar_thiago') {
    acao_tipo = 'DB_OP';
    sql_query = `INSERT INTO giulia_notificacoes_thiago (tipo, origem_numero, origem_nome, resumo, urgencia) VALUES ('recado', '${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, '${esc(p.recado_thiago || dec.resposta || '')}', ${escOrNull(p.urgencia || 'normal')}) RETURNING id, resumo;`;
  } else if (acao === 'encaminhar') {
    acao_tipo = 'DB_OP';
    sql_query = `INSERT INTO giulia_notificacoes_thiago (tipo, origem_numero, origem_nome, resumo, urgencia) VALUES ('encaminhamento', '${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, 'Encaminhei para ' || COALESCE(${escOrNull(p.encaminhar_para)}, '?') || ': ' || ${escOrNull(p.resumo || dec.resposta || '')}, 'info') RETURNING id;`;
  }
}

return [{
  json: {
    eh_thiago: prev.eh_thiago,
    sender_numero: senderNumero,
    sender_nome_push: senderNomePush,
    texto_original: textoSalvarMemoria,
    transcricao_audio: dec.transcricao_audio || '',
    tem_audio: prev.tem_audio,
    acao,
